content.css:
.stf{--stf-mono:"JetBrains Mono",ui-monospace,SFMono-Regular,Menlo,monospace;position:relative;overflow:hidden;background:var(--color-text,#1d1a17);color:var(--color-bg,#fbf9f6);font-family:var(--font-sans,Inter,ui-sans-serif,system-ui,sans-serif)}
.stf::after{content:"SaaSTEMLY";position:absolute;left:50%;bottom:-.24em;transform:translateX(-50%);font-family:var(--stf-mono);font-weight:800;font-size:clamp(5rem,14.5vw,13rem);letter-spacing:-.05em;line-height:1;color:color-mix(in srgb,var(--color-bg,#fbf9f6) 5%,transparent);white-space:nowrap;pointer-events:none;user-select:none}
.stf-inner{position:relative;z-index:1;max-width:1180px;margin:0 auto;padding:4.5rem 1.5rem 7.5rem}
.stf-grid{display:grid;grid-template-columns:2fr 1fr 1fr 1.4fr;gap:2.5rem}
.stf-brand{display:flex;flex-direction:column;gap:1rem;align-items:flex-start}
.stf-logo{display:inline-flex;align-items:center;gap:.6rem;font-family:var(--stf-mono);font-size:1rem;font-weight:800;letter-spacing:.09em;color:var(--color-bg,#fbf9f6);text-decoration:none}
.stf-mark{display:block;width:28px;height:28px}
.stf-tagline{margin:0;max-width:30rem;font-size:.9375rem;line-height:1.7;color:color-mix(in srgb,var(--color-bg,#fbf9f6) 62%,transparent)}
.stf-social{display:flex;gap:1rem;font-family:var(--stf-mono);font-size:.75rem;letter-spacing:.08em;text-transform:uppercase}
.stf-social a{color:color-mix(in srgb,var(--color-bg,#fbf9f6) 70%,transparent);text-decoration:none}
.stf-social a:hover{color:var(--color-brand,#e2603a)}
.stf-heading{margin:0 0 1rem;font-family:var(--stf-mono);font-size:.6875rem;font-weight:700;letter-spacing:.16em;text-transform:uppercase;color:var(--color-brand,#e2603a)}
.stf-heading::before{content:"// ";opacity:.6}
.stf-links{display:flex;flex-direction:column;gap:.6rem;font-size:.9rem}
.stf-links a{color:color-mix(in srgb,var(--color-bg,#fbf9f6) 72%,transparent);text-decoration:none;transition:color 130ms ease}
.stf-links a:hover{color:var(--color-bg,#fbf9f6)}
.stf-col > :not(.stf-heading){color:color-mix(in srgb,var(--color-bg,#fbf9f6) 72%,transparent)}
.stf-col p{margin:0 0 .5rem;font-size:.9rem;line-height:1.7}
.stf-col a{color:color-mix(in srgb,var(--color-bg,#fbf9f6) 85%,transparent)}
.stf-bottom{display:flex;flex-wrap:wrap;align-items:center;gap:1.25rem 2rem;margin-top:3.5rem;padding-top:1.5rem;border-top:1px solid color-mix(in srgb,var(--color-bg,#fbf9f6) 14%,transparent)}
.stf-copy{margin:0;font-family:var(--stf-mono);font-size:.75rem;letter-spacing:.02em;color:color-mix(in srgb,var(--color-bg,#fbf9f6) 55%,transparent)}
.stf-legal{display:flex;gap:1.25rem;font-family:var(--stf-mono);font-size:.75rem}
.stf-legal a{color:color-mix(in srgb,var(--color-bg,#fbf9f6) 62%,transparent);text-decoration:none}
.stf-legal a:hover{color:var(--color-bg,#fbf9f6)}
.stf-bottom [data-theme-switcher]{margin-inline-start:auto}
@media (max-width:940px){.stf-grid{grid-template-columns:1fr 1fr}.stf-brand{grid-column:1/-1}}
@media (max-width:560px){.stf-grid{grid-template-columns:1fr}.stf-inner{padding:3.25rem 1.5rem 5.5rem}}
